mapper.select:
select b.oa_user_id, b.cfg_id, b.x_user_id as wx_userid, r.lastname as oa_name, r.loginid as oa_code, r.systemlanguage as language from ${userBindTable} b left join hrmresource r on r.id = b.oa_user_id where b.bind_state = 1 and b.cfg_id in (select cfg.id from ${cfgTable} cfg where cfg.type = 2) and b.x_user_id is not null and b.x_user_id <> ''
and b.cfg_id = #{cfgId}
and b.oa_user_id in
#{id}
order by b.cfg_id, b.oa_user_id

select b.oa_user_id, b.cfg_id, b.x_user_id as wx_userid, r.lastname as oa_name, r.loginid as oa_code, r.systemlanguage as language from ${userBindTable} b left join hrmresource r on r.id = b.oa_user_id where b.bind_state = 1 and b.cfg_id in (select cfg.id from ${cfgTable} cfg where cfg.type = 2) and b.x_user_id in
#{wxid}
order by b.cfg_id

select id from hrmresource
where loginid in

    #{account}

or workcode in

    #{account}

order by id
